entries[114049] = { ["name"] = "Ascendance", ["text"] = "2.5% of base mana\nInstant 3 min cooldown\nThe Shaman transforms into a being of raw elemental energy for 15 sec.\n\nElemental:\nWhile in the form of a Flame Ascendant, Lava Burst has no cooldown and Chain Lightning is empowered to become Lava Beam.\n\nEnhancement:\nWhile in the form of an Air Ascendant, auto-attacks and Stormstrike become Wind attacks, bypassing armor, and having a 30 yard range.\n\nRestoration:\nWhile in the form of a Water Ascendant, all healing done is duplicated and distributed evenly among nearby allies." }
entries[114050] = { ["name"] = "Ascendance", ["text"] = "40 yd range\nInstant 3 min cooldown\nTransform into a Flame Ascendant for 15 sec, instantly casting a Flame Shock and a 100% effectiveness Lava Burst at up to 6 nearby enemies.\n\nWhile ascended, Elemental Overload damage is increased by 150% and spells affected by your Mastery: Elemental Overload cause 1 additional Elemental Overload." }
